const WM_PAINT: u32 = 0x000F;
const WM_LBUTTONUP: u32 = 0x0202;
const WM_NCHITTEST: u32 = 0x0084;
const HTCLIENT: u32 = 1;
const WM_MOUSEACTIVATE: u32 = 0x0021;
const MA_NOACTIVATE: u32 = 3;
